const lead = $('Um lead por vez').first().json;

const primeiroNome = String(lead.nome || '').replace(/\s+/g, ' ').trim().split(' ')[0] || '';
const tentativasFeitas = Number(lead.tentativas || 0);
const etapa = String(lead.etapa || '');

// Frase de reserva por etapa. So e usada se a IA nao responder ou
// devolver algo que nao da pra usar.
const reservaPorEtapa = {
  novo: 'as informacoes do seu caso',
  potencial: 'as informacoes do seu caso',
  qualificado: 'as informacoes do seu caso',
  calculo: 'a estimativa do seu caso',
  acompanhamento: 'a analise do seu caso',
  sem_laudo: 'o documento que pedi'
};
const reserva = reservaPorEtapa[etapa] || 'as informacoes do seu caso';

// Pega o trecho que a IA escreveu
let trecho = '';
try {
  trecho = String($('Escreve o trecho do contexto').first().json.text || '').trim();
} catch (e) {
  trecho = '';
}

// Limpa aspas e pontuacao que a IA possa ter colocado nas pontas
trecho = trecho.replace(/^["'`\s]+/, '').replace(/["'`.!?\s]+$/, '').trim();

// Se veio vazio, com quebra de linha, ou longo demais, usa a reserva.
// Isso garante que uma falha da IA nunca trava nem estraga a mensagem.
const quantidadePalavras = trecho ? trecho.split(/\s+/).length : 0;
if (!trecho || trecho.indexOf('\n') !== -1 || quantidadePalavras > 12) {
  trecho = reserva;
}

const chamaPeloNome = primeiroNome ? ', ' + primeiroNome : '';

// As tres frases sao fixas — so o trecho entre colchetes muda
let texto = '';

if (tentativasFeitas === 0) {
  texto = 'Oi' + chamaPeloNome + '! Esta por ai ainda? So pra confirmar se posso seguir com ' + trecho + '.';
} else if (tentativasFeitas === 1) {
  texto = 'Oi, aqui e da equipe Monteiro Ramalho. Fique a vontade pra responder quando estiver num lugar mais tranquilo — so fica pendente ' + trecho + ' pra eu continuar seu atendimento.';
} else {
  texto = 'Voce esta online? Preciso so confirmar ' + trecho + ' pra continuar seu atendimento.';
}

const memoriaAgente = JSON.stringify({
  type: 'ai',
  data: {
    content: texto,
    tool_calls: [],
    invalid_tool_calls: [],
    additional_kwargs: {},
    response_metadata: {}
  }
});

const corpo = {
  messaging_product: 'whatsapp',
  to: String(lead.telefone),
  type: 'text',
  text: { body: texto }
};

return [{
  json: {
    lead_id: lead.id,
    telefone: String(lead.telefone),
    nome: primeiroNome,
    etapa: etapa,
    numero_da_tentativa: tentativasFeitas + 1,
    trecho_usado: trecho,
    veio_da_ia: trecho !== reserva,
    mensagem_completa: texto,
    memoria_agente: memoriaAgente,
    corpo: corpo
  }
}];

